import{_ as t,o as a,c as d,a3 as n}from"./chunks/framework.BZKbe9n2.js";const p=JSON.parse('{"title":"Sicherung und Updates","description":"","frontmatter":{},"headers":[],"relativePath":"de/administration/backup-and-updates.md","filePath":"de/administration/backup-and-updates.md"}'),r={name:"de/administration/backup-and-updates.md"};function o(s,e,i,c,u,l){return a(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="sicherung-und-updates" tabindex="-1">Sicherung und Updates <a class="header-anchor" href="#sicherung-und-updates" aria-label="Permalink to &quot;Sicherung und Updates&quot;">​</a></h1><h2 id="was-zu-sichern-ist" tabindex="-1">Was zu sichern ist <a class="header-anchor" href="#was-zu-sichern-ist" aria-label="Permalink to &quot;Was zu sichern ist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Daten</th><th>Wie</th></tr></thead><tbody><tr><td>die Datenbank</td><td><code>pg_dump</code> der Datenbank <code>anthology</code>, z. B. täglich</td></tr><tr><td>das Bibliotheks-Volume (<code>/data/library</code>)</td><td>Dateisicherung; es enthält die verwalteten Originale und die Coverbilder</td></tr><tr><td>das Schlüssel-Volume (<code>/data/keys</code>)</td><td>Dateisicherung; ohne es müssen sich alle Geräte neu anmelden</td></tr><tr><td>referenzierte Ordner</td><td>deine eigene Sicherung – Anthology ändert sie nie</td></tr></tbody></table><p>Das Cache-Volume (<code>/data/cache</code>) lässt sich neu aufbauen und braucht keine Sicherung.</p><p>Nach dem Zurückspielen einer älteren Sicherung prüfe das nächste Ergebnis der Systempflege, bevor du eine Löschung bestätigst (siehe <a href="./maintenance">Wartung</a>).</p><h2 id="aktualisieren" tabindex="-1">Aktualisieren <a class="header-anchor" href="#aktualisieren" aria-label="Permalink to &quot;Aktualisieren&quot;">​</a></h2><p>Lies das <a href="https://github.com/anthology-music/anthology/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">Changelog</a> der neuen Version und mache vorher eine Sicherung.</p><ul><li><strong>Feste Version</strong> (ein Installationspaket oder <code>:X.Y.Z</code>): Ändere die Tags auf die neue Version oder entpacke das Paket des neuen Releases über die alten Dateien, dann neu starten (<code>systemctl --user daemon-reload &amp;&amp; systemctl --user restart anthology-pod</code> oder <code>docker compose up -d</code>).</li><li><strong><code>latest</code>:</strong> mit Quadlet die Images mit <code>podman pull</code> holen und <code>systemctl --user restart anthology-pod</code> (oder <code>podman auto-update</code> mit <code>AutoUpdate=registry</code>); mit Compose <code>docker compose pull &amp;&amp; docker compose up -d</code>.</li></ul><p>Datenbank-Migrationen laufen beim Start des Servers automatisch. <strong>Einstellungen › Über Anthology</strong> zeigt die laufende Version.</p>',9)])])}const m=t(r,[["render",o]]);export{p as __pageData,m as default};
